1	export type QuoteResult = { premium: number };
2	
3	export type ScenarioResults = { results: QuoteResult[] };
4	
5	type Item = { type: string };
6	
7	type Step = { op: string; items: Item[] };
8	
9	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
10	
11	const PROCESSING_FEE = 5;
12	
13	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
14	
15	const ITEM_BASE_PREMIUM: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	};
22	
23	const policyBasePremium = (items: Item[]): number =>
24	  items.reduce((sum, item) => sum + ITEM_BASE_PREMIUM[item.type], 0);
25	
26	const quoteStep = (step: Step): QuoteResult => {
27	  const basePremium = policyBasePremium(step.items);
28	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
29	  return {
30	    premium: basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
31	  };
32	};
33	
34	export const runScenario = (scenario: Scenario): ScenarioResults => ({
35	  results: scenario.steps.map(quoteStep),
36	});
37

1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office — quote", () => {
5	  // Simplest case
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const scenario = {
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    };
11	
12	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
13	  });
14	
15	  // Base premiums for main items (newcomer: 0 years, first quote → +10% first insurance)
16	  it("a single sword (base 100 G) for a newcomer → premium 115 G (100 + 10 first insurance + 5 fee)", () => {
17	    const scenario = {
18	      customer: { yearsWithMHPCO: 0 },
19	      steps: [{ op: "quote", items: [{ type: "sword" }] }],
20	    };
21	
22	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
23	  });
24	  it("a single amulet (base 60 G) for a newcomer → premium 71 G (60 + 6 + 5)", () => {
25	    const scenario = {
26	      customer: { yearsWithMHPCO: 0 },
27	      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
28	    };
29	
30	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
31	  });
32	  it("a single staff (base 80 G) for a newcomer → premium 93 G (80 + 8 + 5)", () => {
33	    const scenario = {
34	      customer: { yearsWithMHPCO: 0 },
35	      steps: [{ op: "quote", items: [{ type: "staff" }] }],
36	    };
37	
38	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 93 }] });
39	  });
40	  it("a single potion (base 40 G) for a newcomer → premium 49 G (40 + 4 + 5)", () => {
41	    const scenario = {
42	      customer: { yearsWithMHPCO: 0 },
43	      steps: [{ op: "quote", items: [{ type: "potion" }] }],
44	    };
45	
46	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 49 }] });
47	  });
48	
49	  // Components and the building block
50	  it("2 runes → 50 G base premium (newcomer, first quote: 50 + 5 + 5 = 60 G premium)", () => {
51	    const scenario = {
52	      customer: { yearsWithMHPCO: 0 },
53	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
54	    };
55	
56	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 60 }] });
57	  });
58	  it.todo("3 runes → 60 G base premium (block applies)");
59	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
60	  it.todo("7 runes → 175 G base premium");
61	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
62	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
63	
64	  // Item-specific modifiers
65	  it.todo("a cursed sword adds a 50 % surcharge on the sword's base premium (100 → 150 G base)");
66	  it.todo("a sword with exactly enchantment 5 adds a 30 % high-enchantment surcharge (100 → 130 G base)");
67	  it.todo("a sword with enchantment 4 gets no high-enchantment surcharge (100 G base)");
68	  it.todo("a cursed sword with exactly enchantment 5 gets both surcharges (100 + 50 + 30 = 180 G base)");
69	
70	  // Modifier scope on multi-item policies
71	  it.todo("a cursed sword (100 G) and a plain amulet (60 G) → 210 G before further modifiers and fee (curse adds 50 G, 50 % of the sword only)");
72	
73	  // Policy-wide modifiers
74	  it.todo("a customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
75	  it.todo("a customer with 1 year with MHPCO receives no loyalty discount");
76	  it.todo("every quote carries the 10 % first-insurance surcharge on the policy base premium");
77	  it.todo("the second quote in a scenario receives the 15 % follow-up-contract discount");
78	  it.todo("the first quote in a scenario receives no follow-up-contract discount");
79	  it.todo("the processing fee of 5 G is added at the very end, after all percentage modifiers");
80	
81	  // Rounding
82	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up in MHPCO's favor)");
83	  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
84	
85	  // Integration examples
86	  it.todo("newcomer (0 years, no previous contract) with a cursed steel sword, enchantment 3 → premium 165 G");
87	  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
88	});
89	
90	describe("MHPCO Claim Office — insurance sum and cap", () => {
91	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
92	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
93	  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G (block discount affects the premium only)");
94	  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (based on the unmodified insurance value)");
95	});
96	
97	describe("MHPCO Claim Office — claim", () => {
98	  // Standard reimbursement
99	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G (full reimbursement minus 100 G deductible)");
100	  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G (no enchantment level or material, so no special clause)");
101	
102	  // Deductible per damage event
103	  it.todo("a dragon attack damaging an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible once per damaged item)");
104	
105	  // Enchantment threshold vs. dragon material
106	  it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G (50 % clause, then deductible)");
107	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (both clauses apply; the 50 % rule wins, then deductible)");
108	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (only the dragon-material clause: full reimbursement, then deductible)");
109	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (only the high-enchantment clause: 50 % first, then deductible)");
110	
111	  // Cap exhaustion across successive claims
112	  it.todo("a sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
113	  it.todo("a sword policy (cap 2000 G), second claim of 1500 G after the first → payout 600 G, remainingCap 0 G");
114	
115	  // Multiple items of the same type
116	  it.todo("a policy covering two swords, a dragon attack damaging both → each damage entry gets its own deductible");
117	
118	  // Rounding
119	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down in MHPCO's favor)");
120	});
121	
122	describe("MHPCO Claim Office — errors", () => {
123	  it.todo("a quote with an item of an unknown type (e.g. broomstick) → error");
124	  it.todo("a claim damaging an amulet when only a sword is insured → error");
125	  it.todo("a claim damaging an item of an unknown type → error");
126	  it.todo("a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
127	  it.todo("a claim with a damage entry of amount -200 → error");
128	});
129	
130	describe("MHPCO Claim Office — CLI", () => {
131	  it.todo("reads a JSON scenario from stdin and writes {results: [...]} to stdout with one result per step");
132	  it.todo("the schema example (amulet quote + amulet claim, 5-year customer) produces a premium result and a payout/remainingCap result");
133	  it.todo("exits with a non-zero status code and writes an error description to stderr on an unknown item type, with no results on stdout");
134	  it.todo("exits with a non-zero status code and writes an error description to stderr on an invalid claim");
135	});
